const stockOut = `-- name: StockOut :one
SELECT fn_stock_out($1::bigint, $2::smallint, $3::numeric, $4::movement_kind,
                    $5::doc_kind, $6::bigint, $7::bigint, $8::uuid)::numeric AS unit_cost
`

type StockOutParams struct {
	ItemID     int64           `json:"item_id"`
	LocationID int16           `json:"location_id"`
	Qty        decimal.Decimal `json:"qty"`
	Kind       MovementKind    `json:"kind"`
	RefType    DocKind         `json:"ref_type"`
	RefID      int64           `json:"ref_id"`
	RefLine    *int64          `json:"ref_line"`
	UserID     uuid.UUID       `json:"user_id"`
}

func (q *Queries) StockOut(ctx context.Context, arg StockOutParams) (decimal.Decimal, error) {
	row := q.db.QueryRow(ctx, stockOut,
		arg.ItemID,
		arg.LocationID,
		arg.Qty,
		arg.Kind,
		arg.RefType,
		arg.RefID,
		arg.RefLine,
		arg.UserID,
	)
	var unit_cost decimal.Decimal
	err := row.Scan(&unit_cost)
	return unit_cost, err
}

const stockRows = `-- name: StockRows :many
SELECT sb.item_id, sb.location_id, sb.qty
FROM stock_balance sb
WHERE sb.item_id = ANY($1::bigint[])
`

type StockRowsRow struct {
	ItemID     int64           `json:"item_id"`
	LocationID int16           `json:"location_id"`
	Qty        decimal.Decimal `json:"qty"`
}

func (q *Queries) StockRows(ctx context.Context, itemIds []int64) ([]StockRowsRow, error) {
	rows, err := q.db.Query(ctx, stockRows, itemIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []StockRowsRow{}
	for rows.Next() {
		var i StockRowsRow
		if err := rows.Scan(&i.ItemID, &i.LocationID, &i.Qty); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateItem = `-- name: UpdateItem :execrows
UPDATE item SET category_id = $1, name = $2, attributes = $3, sku = $4,
       hsn_code = $5, gst_rate = $6, base_unit_id = $7, reorder_level = $8,
       updated_at = now()
WHERE id = $9
`

type UpdateItemParams struct {
	CategoryID   int32           `json:"category_id"`
	Name         string          `json:"name"`
	Attributes   []byte          `json:"attributes"`
	Sku          *string         `json:"sku"`
	HsnCode      string          `json:"hsn_code"`
	GstRate      decimal.Decimal `json:"gst_rate"`
	BaseUnitID   int32           `json:"base_unit_id"`
	ReorderLevel decimal.Decimal `json:"reorder_level"`
	ID           int64           `json:"id"`
}

func (q *Queries) UpdateItem(ctx context.Context, arg UpdateItemParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateItem,
		arg.CategoryID,
		arg.Name,
		arg.Attributes,
		arg.Sku,
		arg.HsnCode,
		arg.GstRate,
		arg.BaseUnitID,
		arg.ReorderLevel,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const upsertItemUnit = `-- name: UpsertItemUnit :exec
INSERT INTO item_unit (item_id, unit_id, factor_to_base) VALUES ($1, $2, $3)
ON CONFLICT (item_id, unit_id) DO UPDATE SET factor_to_base = EXCLUDED.factor_to_base
`

type UpsertItemUnitParams struct {
	ItemID       int64           `json:"item_id"`
	UnitID       int32           `json:"unit_id"`
	FactorToBase decimal.Decimal `json:"factor_to_base"`
}

func (q *Queries) UpsertItemUnit(ctx context.Context, arg UpsertItemUnitParams) error {
	_, err := q.db.Exec(ctx, upsertItemUnit, arg.ItemID, arg.UnitID, arg.FactorToBase)
	return err
}
